# The generator of the oracle workbooks of L3 (dc-m3u) and of its remainder (dc-10y) under
# crates/calc-engine/tests/fixtures/:
#
#   powershell -NoProfile -ExecutionPolicy Bypass -File make-l3-oracles.ps1 -OutDir <directory>
#       [-Workbooks l3,dc_10y,dc_10y_iteration]
#
# writes <directory>/<name>/oracle.xlsx for each workbook named (all three by default) by driving
# Excel through COM: it starts an Excel instance of
# its own, enters every formula with Range.Formula (a legacy formula, as a file without
# dynamic-array metadata holds it), saves, and stops only that instance. Unlike the text-written
# fixtures of calc-fml and calc-func, this workbook needs Excel's own authoring: a table
# (ListObject) and names defined relative to a cell. The bytes therefore differ from run to run;
# the committed workbook is the oracle, and `cargo xtask capture` records what Excel calculates
# from it:
#
#   cargo xtask capture --fixture crates/calc-engine/tests/fixtures/l3/oracle.xlsx \
#       --out crates/calc-engine/tests/captures/l3/oracle.capture.json
#
# l3/oracle.xlsx: 3-D references (sheets Ja, Fe, Ma), structured references to the table Sales
# (sheet Tab), names with relative references, calls of unknown names and INDIRECT text naming a
# defined name (sheet Nm), and legacy formulas at the parameters L3 measured (sheet Lg). Two
# areas of L3 have no oracle workbook, since the capture cannot record them: what-if data tables
# (CaptureRecord version 2 has no kind for a dataTable formula, and the capture refuses the
# workbook), and iterative calculation (with a circular reference Excel 16.0 leaves
# Application.CalculationState at xlPending after CalculateFullRebuild, and the capture waits for
# xlDone until it times out). calc-engine's dc_m3u__data_tables and dc_m3u__iteration cases hold
# the values Excel gave for them through COM.
#
# dc-10y gave the capture both (calc-oracle-excel's worker and calc-verdict's FormulaKind), and
# these workbooks measure what L3 left:
#
# dc_10y/oracle.xlsx (iteration off): INDIRECT text naming this workbook (its file name is
# oracle.xlsx, the name the capture's copy and the comparison open it by) or another (sheet Ind);
# what-if data tables made with Range.Table (sheet DT): by column, by row and with two inputs, and
# a formula reading table cells; a 3-D reference at each argument position of each function where
# dc-10y measured what Excel does with one (sheet ThreeD, over sheets Ja, Fe and Ma holding 1, 2
# and 3 in A1; calc-fml's compile.rs, THREE_D_TAKEN); and a range expression at each parameter
# that takes a reference, where dc-10y measured whether Excel intersects it (sheet Lg, over A1:A3
# holding 1, 2 and 3; calc-fml's legacy.rs, AGGREGATE); and dc-6au's rows (sheet Er, over A1:A3
# holding 1, 2 and 3 and B1:B3 holding 2, with Ja, Fe and Ma holding 10, 20, 30 in B1 and 100,
# 200, 300 in A2): the order of argument errors in the COUP functions, WORKDAY.INTL,
# NETWORKDAYS.INTL, CHISQ.TEST, ARRAYTOTEXT and SORTBY, the LAMBDA helpers given no LAMBDA,
# TRIMMEAN's percent, regression with one known y, Z.TEST, TOCOL and TOROW over a 3-D reference,
# TEXTJOIN's delimiters, SHEETS of a value and AGGREGATE's reference form given values.
#
# dc_10y_iteration/oracle.xlsx (iteration on, at most 50 iterations, maximum change 0.0001):
# circular references that converge, that do not, that only INDIRECT's text makes, and formulas
# reading them (sheet It). The values the file stores are what Excel's own calculations while the
# workbook was authored left; the capture calculates once from them, as DNA Calc does.

param(
    [Parameter(Mandatory = $true)][string]$OutDir,
    [string[]]$Workbooks = @('l3', 'dc_10y', 'dc_10y_iteration')
)

Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'
if (-not [System.IO.Path]::IsPathRooted($OutDir)) { $OutDir = Join-Path (Get-Location).Path $OutDir }
# `-File` passes `-Workbooks a,b` as one string.
$Workbooks = @($Workbooks | ForEach-Object { $_ -split ',' })

Add-Type @'
using System;
using System.Runtime.InteropServices;
public static class L3Window {
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint pid);
}
'@

function Save-Workbook($Workbook, [string]$Path) {
    $dir = Split-Path $Path -Parent
    if (-not (Test-Path $dir)) { [void](New-Item -ItemType Directory -Path $dir) }
    if (Test-Path $Path) { Remove-Item $Path }
    $Workbook.SaveAs($Path, 51)
}

function Add-Sheets($Workbook, [string[]]$Names) {
    while ($Workbook.Worksheets.Count -lt $Names.Count) {
        [void]$Workbook.Worksheets.Add([Type]::Missing, $Workbook.Worksheets.Item($Workbook.Worksheets.Count))
    }
    for ($i = 1; $i -le $Names.Count; $i++) { $Workbook.Worksheets.Item($i).Name = $Names[$i - 1] }
}

function Set-Formulas($Sheet, [int]$Column, [int]$FirstRow, [string[]]$Formulas) {
    $row = $FirstRow
    foreach ($formula in $Formulas) {
        $Sheet.Cells.Item($row, $Column).Formula = $formula
        $row++
    }
}

$xl = New-Object -ComObject Excel.Application
$xlPid = 0
[void][L3Window]::GetWindowThreadProcessId([IntPtr]$xl.Hwnd, [ref]$xlPid)
