        '=INDIRECT("Ja:Ma!A1")', '=SUM(Ja:Ma!A1,Ja:Fe!B1)', '=SUM(Ja:Ma!A1:A2 Ja:Ma!A1)', '=COUNTBLANK(Ja:Ma!C1)', '=MODE(Ja:Ma!A1)',
        '=TEXTJOIN(",",TRUE,Ja:Ma!A1)', '=MAX(Ja:Ma!A:A)', '=VARP(Ja:Ma!A1)', '=STDEVA(Ja:Ma!A1:B1)'
