    $t.Range('K1').Formula = '=INDIRECT("L1")+1'
    $t.Range('L1').Formula = '=INDIRECT("K1")/2'
    $t.Range('A5').Formula = '=A6/3+1'
    $t.Range('A6').Formula = '=A5*2'
    $t.Range('B5').Formula = '=IF(A5>1,B5+1,0)'
    $t.Range('C5').Formula = '=F1+D1'
    $t.Activate()
